use std::collections::HashMap;

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Exp {
    Const(i128),
    Var(String),
    Plus(Box<Exp>, Box<Exp>),
    Mult(Box<Exp>, Box<Exp>),
}

/// Evaluate an expression under a store.
/// If a variable is missing, it evaluates to -1.
///
/// Assumption (matches problem statement): integer arithmetic does not overflow.
pub fn eval(e: &Exp, store: &HashMap<String, i128>) -> i128 {
    match e {
        Exp::Const(c) => *c,
        Exp::Var(name) => store.get(name).copied().unwrap_or(-1),
        Exp::Plus(l, r) => eval(l, store) + eval(r, store),
        Exp::Mult(l, r) => eval(l, store) * eval(r, store),
    }
}

/// Perform a single-step peephole optimization at the root only.
/// Does not traverse into sub-expressions.
pub fn optimize(e: Exp) -> Exp {
    match e {
        Exp::Mult(l, r) => {
            // Root-only rules for multiplication.
            match (&*l, &*r) {
                (Exp::Const(0), _) | (_, Exp::Const(0)) => Exp::Const(0),
                (Exp::Const(1), _) => (*r).clone(),
                (_, Exp::Const(1)) => (*l).clone(),
                (Exp::Const(a), Exp::Const(b)) => Exp::Const(a * b),
                _ => Exp::Mult(l, r),
            }
        }
        Exp::Plus(l, r) => {
            // Root-only rules for addition.
            match (&*l, &*r) {
                (Exp::Const(0), _) => (*r).clone(),
                (_, Exp::Const(0)) => (*l).clone(),
                (Exp::Const(a), Exp::Const(b)) => Exp::Const(a + b),
                _ => Exp::Plus(l, r),
            }
        }
        other => other,
    }
}

/// Runtime-checkable correctness helper: verifies eval(e) == eval(optimize(e)) for a given store.
/// (The problem asks for a proof; in Rust we can provide an executable check.)
pub fn optimize_correct(e: Exp, s: &HashMap<String, i128>) -> bool {
    let v1 = eval(&e, s);
    let e_opt = optimize(e);
    let v2 = eval(&e_opt, s);
    v1 == v2
}

